# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_bio_a import B,H
from author_batch200_root_bio_b import BT
WC=[
E('biosphere','英 /ˈbaɪəʊsfɪə/；美 /ˈbaɪoʊsfɪr/','生物圈','把地球上所有生命及其活动环境放在一起，看作一整层相互联系的系统。','bio-“生命” + -sphere“球、圈层”；英语借自德语 Biosphäre。',B+[['德语 Biosphäre → 英语 biosphere','生命 + 圈层 → 地球的生物圈']],'biosphere 包括生命存在的陆地、水域以及相关大气环境。它不是大气层之外又套着一个看得见的壳，而是从生命活动角度划分出的整体。气候、水循环和生物活动会在其中相互影响。','the Earth’s biosphere；changes in the biosphere；protect the biosphere。','biosphere 是全球层面的整体；biome 是雨林、沙漠等大型生态类型；ecosystem 可以是一片更具体的生态系统。',('Changes in climate affect the biosphere.','气候变化会影响生物圈。'),('The study examines exchanges of carbon between the biosphere and the atmosphere.','研究考察生物圈与大气之间的碳交换。'),sources=['https://en.wiktionary.org/wiki/biosphere','https://openstax.org/books/biology-2e/pages/44-1-the-scope-of-ecology']),
E('biome','英 /ˈbaɪəʊm/；美 /ˈbaɪoʊm/','生物群系；大型生态类型','看一大片地区的气候和典型生物，就能把它归入雨林、草原或沙漠等类型。','bio-“生命” + -ome，近代生态学构词；-ome 在这里帮助组成表示整体的名词。',H(B,'近代 bio- + -ome → biome','大型生物群落及其典型环境类别'),'a desert biome 指沙漠这种大型生态类型，不只是某一只骆驼或某一个沙丘。气候，尤其温度和降水，常影响陆地群系的类型；不同分类体系对水域或边界的划分会有所不同。','a forest biome；a desert biome；major terrestrial biomes。','biome 是生态类型；biota 是某地区的生物总体；biomass 则问它们合起来有多大质量。',('Grassland is one of the major terrestrial biomes.','草原是主要陆地生物群系之一。'),('The class compared the plants found in two different biomes.','班上的学生比较了两个不同生物群系中的植物。'),sources=['https://www.etymonline.com/word/biome','https://openstax.org/books/biology-2e/pages/44-2-biogeography']),
E('biota','英 /baɪˈəʊtə/；美 /baɪˈoʊtə/','某地区或某时期的生物总体；生物区系','把某个地方的动物、植物和微生物放进同一份“居民名单”。','经新拉丁 biota，接希腊 biote“生命、生活”及 bios 词族。',B[:1]+[['希腊 biote → 新拉丁 biota → 英语 biota','生命 → 一定范围中的生物总体']],'the biota of a lake 说湖里生活的各种生物，不只鱼，也包括植物和微生物。它常强调“有哪些生物”，不把水温、盐度等非生物条件本身算作成员。这里的居民名单只是理解画面。','marine biota；soil biota；the local biota。','biota 关注生物成员；ecosystem 还包含非生物环境及相互作用。',('Pollution affected the lake’s biota.','污染影响了这座湖的生物群体。'),('The survey recorded changes in the local biota.','调查记录了当地生物区系的变化。'),sources=['https://en.wiktionary.org/wiki/biota','https://www.merriam-webster.com/dictionary/biota']),
E('biomass','英 /ˈbaɪəʊmæs/；美 /ˈbaɪoʊˌmæs/','生物量；作为能源原料的生物质','一处有多少生命，不只可以数个数，也可以把它们的质量加起来。','bio-“生物” + mass“质量、物质总量”，近代英语组合。',H(B,'英语 bio- + mass → biomass','生物的总质量；后来也指可利用的生物质原料'),'生态学中的 biomass 可以说某一区域、某一类生物的总质量，测量时还要说明鲜重、干重等标准。能源语境中 biomass 常指木材、作物残余等生物来源材料。不是名称带 bio，就自动没有环境影响。','plant biomass；total biomass；biomass fuel。','population size 数个体数量；biomass 计质量。同样一百个个体，微生物与大树的生物量差别很大。',('The researchers measured the dry biomass of the plants.','研究者测量了这些植物的干生物量。'),('The facility uses wood residues as biomass fuel.','这座设施把木材残余物用作生物质燃料。'),sources=['https://en.wiktionary.org/wiki/biomass','https://www.eia.gov/energyexplained/biomass/']),
E('biotic','英 /baɪˈɒtɪk/；美 /baɪˈɑːtɪk/','生物的；由生物造成的','环境中那些正在生活、相互影响的成员，以及它们带来的作用。','接希腊 biotikos，经拉丁 bioticus 等形式；可从 bios“生命”理解。',BT,'biotic factors 可以是捕食者、竞争者、寄生生物或其他生命活动的影响。它不单指“生物课相关”，而是生态环境中的生物这一面。读到 biotic stress，可想植物受到病原生物、害虫等造成的压力。','biotic factors；biotic interactions；biotic stress。','biotic 是生物方面的；abiotic 是光照、水温、盐度等非生物方面的。',('Predation is a biotic factor affecting the population.','捕食是影响这个种群的生物因素。'),('The experiment examined biotic interactions in the soil.','实验考察了土壤中的生物相互作用。'),sources=['https://www.etymonline.com/word/biotic','https://openstax.org/books/biology-2e/pages/44-1-the-scope-of-ecology']),
E('abiotic','英 /ˌeɪbaɪˈɒtɪk/；美 /ˌeɪbaɪˈɑːtɪk/','非生物的；不由生命活动直接构成的','同一片池塘里，鱼和藻类在生活，水温和光照则给它们设置环境条件。','a-“非、无” + biotic“生物的”；前面的 a- 是否定构词成分。',H(BT,'英语 a- + biotic → abiotic','非生物的'),'温度、光照、盐度等属于典型 abiotic factors。它不等于“某处完全没有任何生命”，而是在区分某个因素本身属于生物还是非生物。土壤作为整体同时含有生物成员和非生物成分。','abiotic factors；abiotic conditions；abiotic stress。','abiotic 不等于 sterile“无菌的”。无菌关注微生物状态，非生物关注因素类别。',('Temperature is an important abiotic factor.','温度是一项重要的非生物因素。'),('The plants were exposed to abiotic stress from drought.','这些植物承受了干旱带来的非生物胁迫。'),sources=['https://en.wiktionary.org/wiki/abiotic','https://openstax.org/books/biology-2e/pages/44-2-biogeography']),
E('biotope','英 /ˈbaɪəʊtəʊp/；美 /ˈbaɪəˌtoʊp/','生境；环境条件较一致的生物生活区域','先圈出一块环境相对一致的地方，再看哪些生物共同住在这里。','经德语 Biotop，组合 bio-“生命”与希腊 topos“地方”。',B+[['德语 Biotop → 英语 biotope','生命 + 地方 → 生物生活的区域']],'biotope 侧重支持某个生物群落的环境区域，例如条件相近的一片水塘或湿地。它与 habitat 常有重叠；生态学讨论中，habitat 常以某个物种为中心，biotope 更常以一处环境和群落为中心。','a freshwater biotope；a coastal biotope；restore a biotope。','biotope 更偏向生境这块地方；biocoenosis 更偏向在其中相互作用的生物群落。',('The pond forms a small freshwater biotope.','这个池塘形成了一处小型淡水生境。'),('The project aims to restore the damaged biotope.','项目旨在恢复这处受损的生境。'),sources=['https://en.wiktionary.org/wiki/biotope','https://www.merriam-webster.com/dictionary/biotope']),
E('biozone','英 /ˈbaɪəʊzəʊn/；美 /ˈbaɪoʊˌzoʊn/','生物地层带；按化石特征划分的地层单位','不是按岩石的颜色分层，而是看里面保存了哪些化石线索。','bio-“生物” + zone“带、区域”，在地层学中生物证据通常来自化石。',H(B,'英语 bio- + zone → biozone','按生物、化石特征识别的地层区间'),'地质学家可以根据某些化石出现的范围、组合或其他特征识别 biozone，用于对比地层。不同类型的带使用不同定义；它不是自动等于全球同时开始、同时结束的一段时间。','a fossil biozone；identify a biozone；the boundaries of a biozone。','biozone 是按化石内容划分的地层单位；biochron 关注对应的时间区间。岩层与时间要分清。',('The fossils helped the team identify the biozone.','这些化石帮助团队识别了生物地层带。'),('The paper compares the biozone across several sections.','论文对比了几个剖面中的这一生物地层带。'),sources=['https://en.wiktionary.org/wiki/biozone','https://stratigraphy.org/guide/bio']),
E('biochron','英 /ˈbaɪəʊkrɒn/；美 /ˈbaɪoʊˌkrɑːn/','生物时；依据生物记录识别的时间区间〔地质〕','化石留在岩层里；从这些记录推出来的，是一段地质时间。','bio-“生物” + chron“时间”，近代地质学组合词。',H(B,'英语 bio- + chron → biochron','用生物记录识别的时间区间'),'biochron 常指某个生物地层带所代表的时间区间，或由某类生物记录界定的时间。具体界定要看所用分类方案。它不是一块岩石，也不代表这种生物一定同时出现在地球所有地方。','the duration of a biochron；a fossil biochron；correlate biochrons。','biozone 是地层带，biochron 是时间。类似“这一页纸”和“这一页记载的年代”，不能直接当作同一种东西。',('The study estimates the duration of the biochron.','研究估计了这一生物时的持续长度。'),('The author distinguishes the biozone from its corresponding biochron.','作者区分了生物地层带与它对应的生物时。'),sources=['https://www.merriam-webster.com/dictionary/biochron','https://discovery.ucl.ac.uk/10204108/1/Bown%20et%20al.%20Biostrat_AUTHOR%20CHECKED_20May22.pdf']),
E('biocoenosis','美 /ˌbaɪoʊsəˈnoʊsɪs/','生物群落；共同生活并相互作用的生物集合','一处环境里不是每种生物各过各的，它们会吃、竞争、合作，组成一个群落。','bio-“生命” + 与希腊 koinos“共同”相关的成分；德语 Biozönose 是重要命名来源，英语也写 biocenosis。',B+[['德语 Biozönose；希腊生命与共同词族的学术组合','共同生活的生物群落'],['英语 biocoenosis／biocenosis','彼此作用的生物群落']],'这个较专门的词强调一处生境中共同生活、彼此影响的生物。普通生态学文字常直接写 community。它不是只把不同物种的名字并排罗列，还关心它们在环境中的关系。','the biocoenosis of a pond；a marine biocoenosis；changes in the biocoenosis。','biocoenosis 说群落成员及关系；biotope 说它们生活的环境区域。',('The researchers studied the pond’s biocoenosis.','研究者考察了池塘的生物群落。'),('A change in one species can affect the wider biocoenosis.','一个物种的变化可能影响更广的生物群落。'),sources=['https://en.wiktionary.org/wiki/biocoenosis','https://www.merriam-webster.com/dictionary/biocoenosis']),
E('biogeography','英 /ˌbaɪəʊdʒiˈɒɡrəfi/；美 /ˌbaɪoʊdʒiˈɑːɡrəfi/','生物地理学','为什么这种生物住在这里，那种生物却只在另一块大陆上？','bio-“生物” + geography“地理学”，把生命分布与空间、历史联系起来。',H(B,'英语 bio- + geography → biogeography','研究生物地理分布及其原因的学科'),'biogeography 不只画“哪里有什么”的地图，还问分布是怎样形成的：气候、迁移、隔离、地质历史和演化都可能参与。岛屿为何有独特物种，就是典型问题。','island biogeography；historical biogeography；the biogeography of a species。','geography 范围包括自然与人文地理；biogeography 专门关注生物分布及其形成原因。',('Island biogeography helps explain patterns of species diversity.','岛屿生物地理学帮助解释物种多样性的分布规律。'),('The book examines the biogeography of desert plants.','这本书考察沙漠植物的地理分布及其成因。'),sources=['https://en.wiktionary.org/wiki/biogeography','https://openstax.org/books/biology-2e/pages/44-2-biogeography']),
]
